def _related_value(self, field, obj):
    """
    Return the tuple of values of ``obj`` referenced by the (possibly
    multi-column) intermediary relation ``field``.
    """
    return tuple(
        getattr(obj, related.attname)
        for related in field.foreign_related_fields
    )

def _prepare_related_value(self, field, value):
    """
    Prepare a raw primary key (a scalar for a single-column relation,
    a tuple/list for a relation to a model with a composite primary
    key) into the tuple of values stored on the intermediary model.
    """
    local_fields = field.local_related_fields
    if not isinstance(value, (tuple, list)):
        value = (value,)
    if len(value) != len(local_fields):
        raise ValueError(
            "Expected a value with %d element(s) for relation %r, "
            "got %r" % (len(local_fields), field.name, value)
        )
    return tuple(
        local.get_prep_value(part)
        for local, part in zip(local_fields, value, strict=True)
    )

def _target_value(self, obj):
    """
    Return the prepared tuple of intermediary column values pointing
    at ``obj``, accepting either a related model instance or a raw
    primary key.
    """
    from django.db.models import Model

    if isinstance(obj, Model):
        if not isinstance(obj, self.model):
            raise TypeError(
                "'%s' instance expected, got %r"
                % (self.model._meta.object_name, obj)
            )
        if not router.allow_relation(obj, self.instance):
            raise ValueError(
                'Cannot add "%r": instance is on database "%s", '
                'value is on database "%s"'
                % (obj, self.instance._state.db, obj._state.db)
            )
        value = self._related_value(self.target_field, obj)
        if any(part is None for part in value):
            raise ValueError(
                'Cannot add "%r": the value for field "%s" is None'
                % (obj, self.target_field_name)
            )
        return value
    return self._prepare_related_value(self.target_field, obj)

def _link_column_values(self, field_name, value):
    """
    Map a prepared tuple of relation values onto the concrete
    intermediary column attribute names of ``field_name``.
    """
    field = self.through._meta.get_field(field_name)
    return {
        local.attname: part
        for local, part in zip(field.local_related_fields, value, strict=True)
    }

