def _get_target_vals(self, target_field_name, objs):
    """
    Return the set of relation value tuples of ``objs`` referenced by
    the target field. Every value is validated before the set is
    returned, so a single invalid object aborts the whole operation
    before any write happens.
    """
    target_field = self.through._meta.get_field(target_field_name)
    return {self._get_related_value(target_field, obj) for obj in objs}

def _get_missing_target_vals(
    self, source_field_name, target_field_name, db, target_vals
):
    """
    Return the subset of value tuples that aren't already assigned to
    this relationship. Matching uses every column, so two objects that
    merely share one component are never considered equal.
    """
    target_field = self.through._meta.get_field(target_field_name)
    column_names = [f.attname for f in target_field.local_related_fields]
    existing = set(
        self.through._default_manager.using(db)
        .values_list(*column_names)
        .filter(
            **{
                source_field_name: self.related_val,
                "%s__in" % target_field_name: target_vals,
            }
        )
    )
    return target_vals.difference(existing)

